BEGIN;
SELECT pg_advisory_xact_lock(20261027,4);
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM powertrains WHERE id='5d73717d-9a55-414f-80f0-32a57648bc31' AND generation_id='db75a3f3-aaaa-4470-a4a5-5806b59000e7' AND fuel_type='전기' AND battery_kwh=58.3) THEN RAISE EXCEPTION 'EV4 identity changed'; END IF; END $$;
WITH s AS (INSERT INTO public.vehicle_specs (id,generation_id,powertrain_id,length_mm,width_mm,height_mm,wheelbase_mm,combined_efficiency,source_url,verified_at) VALUES ('7fce2f44-dc43-5de4-b10c-66e94e40841a','db75a3f3-aaaa-4470-a4a5-5806b59000e7','5d73717d-9a55-414f-80f0-32a57648bc31',4730,1860,1480,2820,'5.4 km/kWh (EV4 스탠다드 (2WD) · 19인치 · 58.3kWh · 제조사 2026-09-01 카탈로그)','https://www.kia.com/content/dam/kwp/kr/ko/vehicles/pdf/catalog/catalog_ev4.pdf','2026-10-27') ON CONFLICT (id) DO NOTHING RETURNING id), e AS (INSERT INTO public.source_records (id,entity_type,entity_id,source_url,confidence,verified_at,note) VALUES ('e00a4b9d-9686-515a-9313-02976792d5d4','vehicle_specs','7fce2f44-dc43-5de4-b10c-66e94e40841a','https://www.kia.com/content/dam/kwp/kr/ko/vehicles/pdf/catalog/catalog_ev4.pdf','A','2026-10-27','2026-09-01 제작 공식 EV4 카탈로그 p13 표를 시각 대조. 스탠다드 58.3kWh, 19인치 2WD, 복합 5.4/도심 5.7/고속 5.0 km/kWh, 복합 주행거리 354km, 150kW. HTML의 4WD 표기와 충돌하여 PDF의 명시적 2WD 표를 근거로 사양 분리. 제작일은 인증연도 또는 모델연도가 아님.') ON CONFLICT (id) DO NOTHING RETURNING id) SELECT jsonb_build_object('spec_inserted',(SELECT count(*) FROM s),'source_inserted',(SELECT count(*) FROM e),'spec_ids',(SELECT jsonb_agg(id) FROM s),'source_ids',(SELECT jsonb_agg(id) FROM e)) AS mutation;
COMMIT;
